import 'dart:io';import'package:flutter/material.dart';import'package:image_picker/image_picker.dart';import'package:google_mlkit_text_recognition/google_mlkit_text_recognition.dart';
void main()=>runApp(const App());class App extends StatelessWidget{const App({super.key});Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Home());}
class Home extends StatefulWidget{const Home({super.key});State<Home>createState()=>_S();}class _S extends State<Home>{final p=ImagePicker();final rec=TextRecognizer(script:TextRecognitionScript.latin);File? img;String text='';final list=<Map<String,String>>[];Future<void>scan()async{final x=await p.pickImage(source:ImageSource.camera);if(x==null)return;final f=File(x.path);final r=await rec.processImage(InputImage.fromFile(f));setState((){img=f;text=r.text;});}void add(){if(text.isEmpty)return;final m=RegExp(r'[0-9][0-9.,]*').firstMatch(text)?.group(0)??'0';setState(()=>list.add({'amount':m,'text':text.replaceAll('\n',' ')}));}@override void dispose(){rec.close();super.dispose();}Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Quản lý chi tiêu OCR')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Row(children:[Expanded(child:FilledButton.icon(onPressed:scan,icon:const Icon(Icons.camera_alt),label:const Text('Chụp hóa đơn'))),IconButton(onPressed:add,icon:const Icon(Icons.add_circle))]),if(img!=null)SizedBox(height:150,child:Image.file(img!,fit:BoxFit.cover)),Align(alignment:Alignment.centerLeft,child:Text(text.isEmpty?'Chưa nhận diện':text,maxLines:4,overflow:TextOverflow.ellipsis)),const Divider(),Expanded(child:ListView.builder(itemCount:list.length,itemBuilder:(c,i)=>ListTile(leading:const Icon(Icons.receipt),title:Text('Hóa đơn ${i+1}'),subtitle:Text(list[i]['text']!),trailing:Text(list[i]['amount']!))))])));}
